// 計画の U9: 所属のロール (仕様 02 §ロールの権限)。識別子は計画の Q3 で決めた。
// 画面も使うので、ディレクトリ src/lib/server/ の外に置き、Drizzle に依存しない

export const ROLES = ['owner', 'manager', 'staff'] as const;
export type Role = (typeof ROLES)[number];

// D1 から読んだロールと、画面から受け取ったロールを検査する。知らない値は、どれかのロールとして扱わずに
// エラーにする (計画の Q2)。大文字や空白を整えて受け付けない。店舗管理者が「OWNER」を送って、オーナーに
// 関わる操作の判定を避けられないようにするため (設計 04 §スタッフの管理)
export function parseRole(value: string): Role {
	const role = findRole(value);
	if (role === undefined) {
		throw new Error(`ロールの値 ${JSON.stringify(value)} を知らない`);
	}
	return role;
}

// 画面から受け取った値が、3 つのロールのどれかなら、そのロールを返す。知らない値は、エラーにせずに undefined を返す
// (画面の action が、状態 400 で断るため)。大文字や空白を整えない (関数 parseRole と同じ理由)
export function findRole(value: unknown): Role | undefined {
	return ROLES.find((known) => known === value);
}

// ロールの画面での呼び名。店舗管理者は、画面では「店長」と呼ぶ (仕様 01 の店舗管理者の行。#8)
export const ROLE_LABELS: Record<Role, string> = {
	owner: 'オーナー',
	manager: '店長',
	staff: 'スタッフ'
};
